package com.rezoxnemesis.videostudio;
import android.graphics.*;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.*;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(sdk=33,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class SketchPaintMeshTest {
 static JSONObject object(JSONObject mesh)throws Exception{return new JSONObject().put("kind","paint").put("bounds",new JSONObject().put("x",0).put("y",0).put("width",1).put("height",1)).put("paintMesh",mesh);}
 @Test public void nativeRasterAndInvertedTrianglesMustUseTheSameSourceMapping()throws Exception{
  JSONObject mesh=SketchPaintMesh.regular(1,1);mesh.getJSONArray("points").put(3,new JSONArray().put(180/256d).put(200/256d));JSONObject o=object(mesh);SketchPaintMesh.validate(o,1);
  Bitmap source=Bitmap.createBitmap(256,256,Bitmap.Config.ARGB_8888),target=Bitmap.createBitmap(256,256,Bitmap.Config.ARGB_8888);
  try{int[] pixels=new int[256*256];for(int y=0;y<256;y++)for(int x=0;x<256;x++)pixels[y*256+x]=Color.rgb(x,y,0);source.setPixels(pixels,0,256,0,0,256,256);new Canvas(target).drawBitmapMesh(source,1,1,SketchPaintMesh.vertices(o,0,256,256),0,null,0,new Paint());
   for(int[] p:new int[][]{{100,100},{165,110},{120,180}}){double[] uv=SketchPaintMesh.sourceAt(o,0,(p[0]+.5)/256d,(p[1]+.5)/256d);assertNotNull(uv);int actual=target.getPixel(p[0],p[1]);assertEquals("Native red/source U differs at "+p[0]+","+p[1],uv[0]*256,Color.red(actual),1.5);assertEquals("Native green/source V differs",uv[1]*256,Color.green(actual),1.5);}
  }finally{source.recycle();target.recycle();}
 }
 @Test public void strictTopologyKeysAndCollapseBetweenValidPoses()throws Exception{
  JSONObject m=SketchPaintMesh.regular(2,3);assertArrayEquals(new int[]{0,12},SketchPaintMesh.validate(object(m),10));assertThrows(IllegalArgumentException.class,()->SketchPaintMesh.regular(17,1));
  JSONObject wrong=object(m).put("kind","path");assertThrows(IllegalArgumentException.class,()->SketchPaintMesh.validate(wrong,10));
  JSONObject a=SketchPaintMesh.regular(1,1),b=SketchPaintMesh.regular(1,1);b.getJSONArray("points").put(0,new JSONArray().put(1).put(1)).put(1,new JSONArray().put(0).put(1)).put(2,new JSONArray().put(1).put(0)).put(3,new JSONArray().put(0).put(0));
  b.put("keys",new JSONArray().put(new JSONObject().put("frame",0).put("points",a.getJSONArray("points")).put("interpolation","linear")).put(new JSONObject().put("frame",9).put("points",b.getJSONArray("points")).put("interpolation","linear")));assertThrows(IllegalArgumentException.class,()->SketchPaintMesh.validate(object(b),10));
  JSONObject bad=SketchPaintMesh.regular(1,1);bad.getJSONArray("points").put(3,new JSONArray().put(0).put(0));assertThrows(IllegalArgumentException.class,()->SketchPaintMesh.validate(object(bad),1));
  JSONObject nullField=new JSONObject().put("kind","paint").put("paintMesh",JSONObject.NULL);assertThrows(IllegalArgumentException.class,()->SketchPaintMesh.validate(nullField,1));
 }
 static JSONObject load(android.content.Context c,String id)throws Exception{try(SketchProjectStore store=new SketchProjectStore(c)){return store.get(id);}}
 static JSONObject edit(android.content.Context c,String id,long revision,String operation,JSONArray ops)throws Exception{return SketchEditOps.execute(c,"sketch_edit",new JSONObject().put("sketchId",id).put("expectedRevision",revision).put("operationId",operation).put("operations",ops));}
 @Test public void actualPaintPreparationRenderingPickingUndoArchiveAndCelSnapshots()throws Exception{
  java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();try{worker.submit(()->{try{
   android.content.Context c=RuntimeEnvironment.getApplication();String id="mesh_"+java.util.UUID.randomUUID();SketchEditOps.execute(c,"sketch_create",new JSONObject().put("sketchId",id).put("operationId","create").put("width",256).put("height",256).put("frameCount",8).put("background","#00000000"));
   edit(c,id,1,"outline",new JSONArray().put(new JSONObject().put("type","add_object").put("layerId","layer_1").put("object",SketchDocument.object(SketchContourPaintTest.fixture(),"authored_outline"))).put(new JSONObject().put("type","add_paint_cel").put("layerId","layer_1").put("objectId","base").put("exposure",8)));
   JSONObject pin=SketchContourPaint.pin(load(c,id),"authored_outline");edit(c,id,2,"fill",new JSONArray().put(new JSONObject().put("type","paint_fill").put("objectId","base").put("strokeId","fill").put("contourObjectId","authored_outline").put("expectedContourSha256",pin.getString("sha256")).put("color","#FFFFFFFF")).put(new JSONObject().put("type","delete_object").put("objectId","authored_outline")));
   JSONObject before=load(c,id),source=SketchDocument.object(before,"base").getJSONObject("paint");String original=SketchDocument.canonical(before);
   JSONObject request=new JSONObject().put("sketchId",id).put("expectedRevision",3).put("paintMeshPreparation",new JSONObject().put("objectId","base").put("columns",2).put("rows",2));JSONObject preparation=SketchEditOps.execute(c,"sketch_inspect",request).getJSONObject("paintMeshPreparation");assertEquals(original,SketchDocument.canonical(load(c,id)));assertEquals(source.getString("sha256"),preparation.getString("sourcePaintSha256"));
   JSONObject operation=preparation.getJSONObject("operation"),mesh=operation.getJSONObject("patch").getJSONObject("paintMesh");JSONArray first=new JSONArray(mesh.getJSONArray("points").toString()),shift=new JSONArray(first.toString());for(int i=0;i<shift.length();i++)shift.getJSONArray(i).put(0,shift.getJSONArray(i).getDouble(0)+.1);mesh.put("keys",new JSONArray().put(new JSONObject().put("frame",0).put("points",first).put("interpolation","hold")).put(new JSONObject().put("frame",4).put("points",shift).put("interpolation","hold")));
   edit(c,id,3,"mesh",new JSONArray().put(operation));JSONObject d=load(c,id);assertEquals(SketchDocument.canonical(source),SketchDocument.canonical(SketchDocument.object(d,"base").getJSONObject("paint")));assertThrows(IllegalStateException.class,()->SketchEditOps.execute(c,"sketch_inspect",request));
   assertThrows(IllegalArgumentException.class,()->SketchPaintMeshPrepare.prepare(c,new JSONObject().put("sketchId",id).put("expectedRevision",4).put("objectId","base").put("columns",2).put("rows",2)));
   try(SketchFrameRenderer renderer=new SketchFrameRenderer(c,d)){Bitmap frame=renderer.render(4,false);try{assertEquals(Color.WHITE,frame.getPixel(77,51));assertEquals(0,frame.getPixel(154,128));}finally{frame.recycle();}renderer.prepareRasterResources(512,4);assertEquals("base",SketchFrameRenderer.hitTest(d,4,.3,.2,.001,renderer.imageSelections()));assertNull(SketchFrameRenderer.hitTest(d,4,.6,.5,.001,renderer.imageSelections()));assertNull(SketchFrameRenderer.hitTest(d,4,.15,.05,.001,renderer.imageSelections()));assertTrue(renderer.preparedSelectionBytes()<=8192);}
   try(SketchFrameRenderer editor=new SketchFrameRenderer(c,d)){editor.enableImageSelections();Bitmap initialRaster=editor.render(0,false,128,null),posed=editor.render(4,false,128,null);initialRaster.recycle();posed.recycle();assertEquals("base",SketchFrameRenderer.hitTest(d,4,.3,.2,.001,editor.imageSelections()));assertNull(SketchFrameRenderer.hitTest(d,4,.6,.5,.001,editor.imageSelections()));}
   JSONObject staticCel=SketchShapeKeys.sampled(SketchDocument.object(d,"base"),4);assertEquals(0,staticCel.getJSONObject("paintMesh").getJSONArray("keys").length());assertEquals(.1,staticCel.getJSONObject("paintMesh").getJSONArray("points").getJSONArray(0).getDouble(0),0);
   JSONObject timeline=SketchDocument.copy(d);SketchCelOps.apply(timeline,new JSONObject().put("type","insert_frame").put("frame",2));assertEquals(5,SketchDocument.object(timeline,"base").getJSONObject("paintMesh").getJSONArray("keys").getJSONObject(1).getInt("frame"));SketchDocument.validate(timeline);SketchCelOps.apply(timeline,new JSONObject().put("type","delete_frame").put("frame",2));SketchDocument.validate(timeline);assertEquals(4,SketchDocument.object(timeline,"base").getJSONObject("paintMesh").getJSONArray("keys").getJSONObject(1).getInt("frame"));
   SketchPaintArchive.Prepared archive=SketchPaintArchive.prepare(c,new JSONObject().put("sketchId",id).put("expectedRevision",4).put("operationId","archive"));JSONObject restored=SketchPaintArchive.restoreFile(c,archive.file,SketchProjectStore.fileHash(archive.file),"restore_mesh","Mesh restore");JSONObject restoredDocument=load(c,restored.getString("sketchId"));assertEquals(SketchDocument.canonical(mesh),SketchDocument.canonical(SketchDocument.object(restoredDocument,"base").getJSONObject("paintMesh")));try(SketchFrameRenderer renderer=new SketchFrameRenderer(c,restoredDocument)){Bitmap frame=renderer.render(4,false);try{assertEquals(Color.WHITE,frame.getPixel(77,51));assertEquals(0,frame.getPixel(154,128));}finally{frame.recycle();}}
   SketchEditOps.execute(c,"sketch_undo",new JSONObject().put("sketchId",id).put("expectedRevision",4).put("operationId","undo"));assertFalse(SketchDocument.object(load(c,id),"base").has("paintMesh"));SketchEditOps.execute(c,"sketch_redo",new JSONObject().put("sketchId",id).put("expectedRevision",5).put("operationId","redo"));assertEquals(source.getString("sha256"),SketchDocument.object(load(c,id),"base").getJSONObject("paint").getString("sha256"));
   return null;
  }catch(Exception failure){throw new RuntimeException(failure);}}).get(90,java.util.concurrent.TimeUnit.SECONDS);}finally{worker.shutdownNow();}
 }
 @Test public void regularGridPreservesEveryTransformedSemitransparentPixelWithAndWithoutPreviewCache()throws Exception {
  java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();SketchFrameRenderer[] prepared=null;java.io.File evidence=new java.io.File("build/native-paint-mesh-neutrality/"+java.util.UUID.randomUUID());assertTrue(evidence.mkdirs());
  try{prepared=worker.submit(()->{try{
   android.content.Context c=RuntimeEnvironment.getApplication();String id="neutral_mesh_"+java.util.UUID.randomUUID();SketchEditOps.execute(c,"sketch_create",new JSONObject().put("sketchId",id).put("operationId","create").put("width",512).put("height",768).put("frameCount",1).put("background","#00000000"));edit(c,id,1,"paint",new JSONArray().put(new JSONObject().put("type","add_paint_cel").put("layerId","layer_1").put("objectId","paint")));edit(c,id,2,"pigment",new JSONArray().put(new JSONObject().put("type","paint_stroke").put("objectId","paint").put("strokeId","asymmetric_alpha").put("points",new JSONArray("[[.01,.13,.3],[.27,.37,.9],[.52,.71,.4],[.93,.90,.7]]")).put("brush",new JSONObject().put("mode","paint").put("color","#806050A0").put("sizePx",80).put("opacity",.73).put("flow",.65).put("hardness",.25).put("spacing",.1))));
   JSONObject plain=load(c,id);SketchEditOps.apply(plain,new JSONObject().put("type","set_transform").put("objectId","paint").put("transform",new JSONObject().put("rotation",27).put("anchorX",.47).put("anchorY",.63).put("x",.03).put("y",-.06).put("opacity",.73)));SketchEditOps.apply(plain,new JSONObject().put("type","set_transform").put("layerId","layer_1").put("transform",new JSONObject().put("rotation",-7).put("scaleX",.9).put("scaleY",1.1).put("opacity",.63)));JSONObject mesh=SketchDocument.copy(plain);SketchDocument.object(mesh,"paint").put("paintMesh",SketchPaintMesh.regular(5,7));assertTrue(SketchPaintMesh.regularAt(SketchDocument.object(mesh,"paint"),0));
   SketchFrameRenderer a=new SketchFrameRenderer(c,plain),b=new SketchFrameRenderer(c,mesh);Bitmap x=a.render(0,false),y=b.render(0,false);try{assertNativePixels(x,y,evidence,"full");}finally{x.recycle();y.recycle();}a.prepareRasterResources(128,0);b.prepareRasterResources(128,0);return new SketchFrameRenderer[]{a,b};
  }catch(Exception failure){throw new RuntimeException(failure);}}).get(90,java.util.concurrent.TimeUnit.SECONDS);
   Bitmap x=Bitmap.createBitmap(512,768,Bitmap.Config.ARGB_8888),y=Bitmap.createBitmap(512,768,Bitmap.Config.ARGB_8888);try{prepared[0].draw(new Canvas(x),0,false);prepared[1].draw(new Canvas(y),0,false);assertNativePixels(x,y,evidence,"cached");}finally{x.recycle();y.recycle();}
  }finally{worker.shutdownNow();if(prepared!=null)for(SketchFrameRenderer renderer:prepared)renderer.close();}
 }
 @Test public void tallNativePaintSourceKeepsItsRealDimensionsBeyondThePreviewLimit()throws Exception {
  java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();try{worker.submit(()->{try{
   android.content.Context c=RuntimeEnvironment.getApplication();String id="tall_mesh_"+java.util.UUID.randomUUID();SketchEditOps.execute(c,"sketch_create",new JSONObject().put("sketchId",id).put("operationId","new").put("width",576).put("height",1280).put("frameCount",1).put("background","#00000000"));edit(c,id,1,"cel",new JSONArray().put(new JSONObject().put("type","add_paint_cel").put("layerId","layer_1").put("objectId","paint")));edit(c,id,2,"pigment",new JSONArray().put(new JSONObject().put("type","paint_stroke").put("objectId","paint").put("strokeId","tall_owned").put("points",new JSONArray("[[.5,.6,1]]")).put("brush",new JSONObject().put("mode","paint").put("color","#FF335577").put("sizePx",40))));
   JSONObject before=load(c,id),descriptor=SketchDocument.object(before,"paint").getJSONObject("paint"),args=new JSONObject().put("sketchId",id).put("expectedRevision",3).put("paintMeshPreparation",new JSONObject().put("objectId","paint").put("columns",16).put("rows",16));String unchanged=SketchDocument.canonical(before);JSONObject prepared=SketchEditOps.execute(c,"sketch_inspect",args).getJSONObject("paintMeshPreparation");assertEquals(unchanged,SketchDocument.canonical(load(c,id)));
   try(SketchPaintStore store=new SketchPaintStore(c,id)){assertThrows(IllegalArgumentException.class,()->store.render(descriptor,1280,null));Bitmap source=store.renderSource(descriptor);try{assertEquals(576,source.getWidth());assertEquals(1280,source.getHeight());assertEquals(0xff335577,source.getPixel(288,768));assertEquals(0,source.getPixel(20,20));}finally{source.recycle();}}
   JSONObject patch=prepared.getJSONObject("operation"),mesh=patch.getJSONObject("patch").getJSONObject("paintMesh");JSONArray points=mesh.getJSONArray("points");for(int i=0;i<points.length();i++)points.getJSONArray(i).put(0,points.getJSONArray(i).getDouble(0)+.125);edit(c,id,3,"grid",new JSONArray().put(patch));JSONObject posed=load(c,id);assertEquals(descriptor.getString("sha256"),SketchDocument.object(posed,"paint").getJSONObject("paint").getString("sha256"));try(SketchFrameRenderer renderer=new SketchFrameRenderer(c,posed)){renderer.enableImageSelections();Bitmap nativeFrame=renderer.render(0,false);try{assertEquals(576,nativeFrame.getWidth());assertEquals(1280,nativeFrame.getHeight());assertEquals(0xff335577,nativeFrame.getPixel(360,768));assertEquals(0,nativeFrame.getPixel(288,768));}finally{nativeFrame.recycle();}assertEquals("paint",SketchFrameRenderer.hitTest(posed,0,.625,.6,.001,renderer.imageSelections()));assertNull(SketchFrameRenderer.hitTest(posed,0,.5,.6,.001,renderer.imageSelections()));renderer.prepareRasterResources(360,0);assertEquals("paint",SketchFrameRenderer.hitTest(posed,0,.625,.6,.001,renderer.imageSelections()));}
   return null;
  }catch(Exception failure){throw new RuntimeException(failure);}}).get(90,java.util.concurrent.TimeUnit.SECONDS);}finally{worker.shutdownNow();}
 }
 static void assertNativePixels(Bitmap wanted,Bitmap actual,java.io.File evidence,String mode)throws Exception {
  for(Object[] row:new Object[][]{{"before",wanted},{"with-grid",actual}})try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(evidence,mode+"-"+row[0]+".png"))){assertTrue(((Bitmap)row[1]).compress(Bitmap.CompressFormat.PNG,100,out));}int[] x=new int[wanted.getWidth()*wanted.getHeight()],y=new int[x.length];wanted.getPixels(x,0,wanted.getWidth(),0,0,wanted.getWidth(),wanted.getHeight());actual.getPixels(y,0,actual.getWidth(),0,0,actual.getWidth(),actual.getHeight());assertArrayEquals(mode+" regular-grid neutrality must preserve all RGBA values",x,y);
 }
}
